  "دهان":{faMeaning:"بخشی از صورت که برای خوردن، آشامیدن و تولید گفتار به کار می‌رود.",faSynonyms:["دَم","محل ورود غذا"],enMeaning:"The opening in the face used for eating, drinking, and speaking.",enSynonyms:["mouth","oral cavity"],arMeaning:"فتحة في الوجه تُستخدم للأكل والشرب والكلام.",arSynonyms:["فم","تجويف الفم"]},
  "زبان":{faMeaning:"اندام ماهیچه‌ای در دهان که در چشیدن، بلعیدن و تولید صداهای گفتار نقش دارد؛ همچنین به معنای زبان گفتاری یک جامعه است.",faSynonyms:["اندام چشایی","زبان گفتاری (در معنای زبانی)"],enMeaning:"The muscular organ in the mouth used for tasting and speech; also a system of communication used by a community.",enSynonyms:["tongue","language"],arMeaning:"عضو عضلي في الفم يُستخدم للتذوّق والنطق؛ ويعني أيضاً نظام التواصل بين أفراد المجتمع.",arSynonyms:["لسان","لغة"]},
  "گوش":{faMeaning:"اندام شنوایی که صدا را دریافت می‌کند؛ بخش بیرونی آن در دو طرف سر دیده می‌شود.",faSynonyms:["اندام شنوایی"],enMeaning:"The organ of hearing that detects sound.",enSynonyms:["ear","hearing organ"],arMeaning:"عضو السمع الذي يستقبل الأصوات.",arSynonyms:["أذن","سمع"]},
  "مژه":{faMeaning:"موهای کوتاهی که در لبهٔ پلک قرار دارند و از چشم در برابر گردوغبار محافظت می‌کنند.",faSynonyms:["موی پلک"],enMeaning:"The short hairs along the edge of the eyelid that help protect the eye.",enSynonyms:["eyelash","lash"],arMeaning:"الشعيرات القصيرة على حافة الجفن التي تساعد على حماية العين.",arSynonyms:["رِمش","أهداب"]},
  "گونه":{faMeaning:"بخش برجستهٔ صورت در دو طرف بینی و زیر چشم‌ها.",faSynonyms:["بَناگوش (در برخی کاربردها)","لپ (گفتاری)"],enMeaning:"The rounded side area of the face below the eyes and beside the nose.",enSynonyms:["cheek"],arMeaning:"الجزء المستدير من الوجه أسفل العين وبجانب الأنف.",arSynonyms:["خدّ","وجنة"]},
  "بینی":{faMeaning:"اندام بویایی در مرکز صورت که در تنفس نیز نقش دارد.",faSynonyms:["دماغ (در برخی گونه‌های فارسی)"],enMeaning:"The organ in the centre of the face used for smelling and as an airway.",enSynonyms:["nose"],arMeaning:"عضو الشمّ في وسط الوجه، وله دورٌ في التنفّس.",arSynonyms:["أنف"]},
  "لب":{faMeaning:"بخش نرم و بیرونی دهان که در خوردن، سخن گفتن و حالت‌های چهره نقش دارد.",faSynonyms:["لب‌ها","کنارهٔ دهان"],enMeaning:"The soft, movable edge of the mouth used in eating, speaking, and facial expression.",enSynonyms:["lip","lips"],arMeaning:"الجزء اللين المتحرّك من حافة الفم، ويُستخدم في الأكل والكلام وتعابير الوجه.",arSynonyms:["شفة","شفاه"]},
  "چانه":{faMeaning:"بخش پایینی صورت، زیر لب پایین.",faSynonyms:["زیرچانه (ناحیهٔ زیر چانه)"],enMeaning:"The lower part of the face below the lower lip.",enSynonyms:["chin"],arMeaning:"الجزء السفلي من الوجه أسفل الشفة السفلى.",arSynonyms:["ذقن"]},
  "پیشانی":{faMeaning:"بخش بالایی صورت، میان خط رویش مو و ابروها.",faSynonyms:["جبین"],enMeaning:"The upper part of the face between the eyebrows and the hairline.",enSynonyms:["forehead","brow"],arMeaning:"الجزء العلوي من الوجه بين الحاجبين ومنبت الشعر.",arSynonyms:["جبهة","جبين"]},
  "چاق":{faMeaning:"دارای وزن یا حجم بدن نسبتاً زیاد؛ در کاربرد محترمانه بهتر است از توصیف خنثی‌تر استفاده شود.",faSynonyms:["فربه","درشت‌اندام"],enMeaning:"Having a relatively large or heavy body; a potentially sensitive description of a person.",enSynonyms:["fat","overweight","plump (softer)"],arMeaning:"ذو وزنٍ أو حجم جسماني كبير نسبياً؛ وقد يكون الوصف حساساً عند الحديث عن الأشخاص.",arSynonyms:["بدين","ممتلئ الجسم"]},
  "لاغر":{faMeaning:"دارای وزن یا حجم بدن کم و اندام باریک.",faSynonyms:["باریک‌اندام","نحیف"],enMeaning:"Having a thin or slender body.",enSynonyms:["thin","slim","slender"],arMeaning:"ذو جسمٍ نحيف أو قليل الوزن.",arSynonyms:["نحيف","هزيل"]},
