  "می‌توانم":{faMeaning:"صورت اول‌شخص مفردِ فعل «توانستن» در زمان حال؛ برای بیان توانایی یا امکان به کار می‌رود.",faSynonyms:["توانایی دارم","قادرم"],enMeaning:"The first-person singular present form of 'can/to be able'; expresses ability or possibility.",enSynonyms:["I can","I am able to"],arMeaning:"صيغة المتكلّم المفرد من فعل الاستطاعة في المضارع، وتدلّ على القدرة أو الإمكان.",arSynonyms:["أستطيع","أقدر"]},
  "کارخانه":{faMeaning:"ساختمان یا مجموعه‌ای صنعتی که در آن کالا یا محصول با ابزار و ماشین‌آلات تولید می‌شود.",faSynonyms:["واحد تولیدی","کارگاه بزرگ صنعتی"],enMeaning:"An industrial building or complex where goods are manufactured using machinery and equipment.",enSynonyms:["factory","plant","manufacturing facility"],arMeaning:"مبنى أو مجمّع صناعي تُنتج فيه السلع باستعمال الآلات والمعدّات.",arSynonyms:["مصنع","منشأة صناعية"]},
  "دفترچهٔ راهنما":{faMeaning:"متنی کوتاه یا کتابچه‌ای که روش استفاده، نصب یا نگهداری یک وسیله یا سامانه را توضیح می‌دهد.",faSynonyms:["راهنمای استفاده","دفترچهٔ دستورالعمل"],enMeaning:"A small booklet explaining how to use, install, or maintain a device or system.",enSynonyms:["user manual","instruction booklet","guidebook"],arMeaning:"كتيّب يشرح طريقة استعمال جهازٍ أو نظامٍ أو تركيبه أو صيانته.",arSynonyms:["دليل الاستخدام","كتيّب التعليمات"]},
  "نقشه":{faMeaning:"طرح یا تصویری که جای مکان‌ها، مسیرها یا بخش‌های یک منطقه یا ساختمان را نشان می‌دهد.",faSynonyms:["نقشهٔ جغرافیایی","طرح راهنما"],enMeaning:"A drawing or representation showing the locations of places, routes, or parts of an area or building.",enSynonyms:["map","plan","diagram"],arMeaning:"رسم أو تمثيل يوضّح مواقع الأماكن أو الطرق أو أجزاء منطقة أو مبنى.",arSynonyms:["خريطة","مخطّط"]},
  "مسافرخانه":{faMeaning:"محل اقامت ساده و معمولاً کم‌هزینه برای مسافران.",faSynonyms:["مهمان‌پذیر","اقامتگاه ساده"],enMeaning:"A simple, usually inexpensive place where travellers can stay.",enSynonyms:["guesthouse","inn","budget lodging"],arMeaning:"مكان إقامة بسيط، وغالباً منخفض التكلفة، للمسافرين.",arSynonyms:["نُزُل","بيت ضيافة"]},
