  "عمق":{faMeaning:"اندازهٔ فاصله از سطح تا بخش پایین‌تر یا درونی‌تر چیزی؛ در برابر سطحی‌بودن.",faSynonyms:["ژرفا","گودی"],enMeaning:"The distance from a surface to the bottom or deepest part of something.",enSynonyms:["depth","deepness"],arMeaning:"مقدار المسافة من السطح إلى أسفل الشيء أو أعمق أجزائه.",arSynonyms:["عمق","غور"]},
  "مروارید":{faMeaning:"گوهر سخت و درخشانی که درون برخی صدف‌ها شکل می‌گیرد و در زیورآلات به کار می‌رود.",faSynonyms:["دُر","گوهر دریایی"],enMeaning:"A hard, lustrous gem formed inside certain molluscs and used in jewellery.",enSynonyms:["pearl"],arMeaning:"جوهرة صلبة لامعة تتكوّن داخل بعض المحار وتُستخدم في الحلي.",arSynonyms:["لؤلؤة","لؤلؤ"]},
  "صدف":{faMeaning:"پوستهٔ سخت برخی جانوران دریایی؛ گاهی به خود جانور صدف‌دار نیز گفته می‌شود.",faSynonyms:["پوستهٔ صدف","محار (برای جانور)"],enMeaning:"The hard shell of certain sea animals; also refers to some shellfish.",enSynonyms:["shell","seashell","oyster shell"],arMeaning:"القشرة الصلبة لبعض الكائنات البحرية، وقد يُطلق اللفظ على الحيوان ذي الصدفة.",arSynonyms:["صدفة","محار"]},
  "دشت":{faMeaning:"زمین گسترده و نسبتاً هموار که معمولاً پوشش گیاهی کم یا پراکنده دارد.",faSynonyms:["جلگه","هموارگاه"],enMeaning:"A broad, relatively flat area of land, often with sparse vegetation.",enSynonyms:["plain","flatland","open plain"],arMeaning:"أرض واسعة مستوية نسبياً، وقد يكون غطاؤها النباتي قليلاً.",arSynonyms:["سهل","أرض منبسطة"]},
