  "کوهستانی":{faMeaning:"دارای کوه‌های فراوان یا واقع‌شده در ناحیه‌ای که بخش بزرگی از آن کوه است.",faSynonyms:["کوهی","کوه‌دار"],enMeaning:"Having many mountains or located in a mountainous region.",enSynonyms:["mountainous","rugged"],arMeaning:"ذو جبال كثيرة أو واقعٌ في منطقة يغلب عليها الطابع الجبلي.",arSynonyms:["جبليّ","كثير الجبال"]},
  "آموختن":{faMeaning:"کسب دانش یا مهارت از راه آموزش، تمرین یا تجربه؛ صورتی رسمی‌تر از «یاد گرفتن».",faSynonyms:["یاد گرفتن","فراگرفتن"],enMeaning:"To acquire knowledge or a skill through instruction, practice, or experience; a more formal word for 'learn'.",enSynonyms:["learn","acquire","master"],arMeaning:"اكتساب العلم أو المهارة بالتعليم أو التدريب أو التجربة.",arSynonyms:["تعلّم","اكتسب","أتقن"]},
  "سرزمین":{faMeaning:"ناحیه یا گستره‌ای از زمین که معمولاً با یک مردم، کشور یا ویژگی طبیعی و فرهنگی شناخته می‌شود.",faSynonyms:["بوم","کشور (در برخی بافت‌ها)","ناحیه"],enMeaning:"A region or expanse of land, often associated with a people, country, or distinctive culture.",enSynonyms:["land","territory","region","homeland"],arMeaning:"منطقة أو مساحة من الأرض ترتبط غالباً بشعبٍ أو دولةٍ أو خصائص طبيعية وثقافية.",arSynonyms:["أرض","إقليم","وطن"]},
  "گلستان":{faMeaning:"باغ یا محلی پر از گل؛ همچنین نام یک استان در شمال ایران است.",faSynonyms:["باغ گل","گلزار"],enMeaning:"A flower garden; also the name of a province in northern Iran.",enSynonyms:["flower garden","rose garden","Golestan (province)"],arMeaning:"بستانٌ مليء بالزهور؛ وهو أيضاً اسم محافظة في شمال إيران.",arSynonyms:["بستان أزهار","حديقة زهور","كلستان (اسم مكان)"]},
  "بوستان":{faMeaning:"باغ یا فضای سبزِ درخت‌کاری‌شده برای زیبایی، استراحت یا گردش.",faSynonyms:["باغ","پارک"],enMeaning:"A garden or planted green space used for beauty, relaxation, or recreation.",enSynonyms:["garden","park","orchard (depending on context)"],arMeaning:"حديقة أو مساحة خضراء مزروعة بالأشجار للزينة أو الراحة أو التنزّه.",arSynonyms:["بستان","حديقة","منتزه"]},
  "همشهری":{faMeaning:"کسی که با شخص دیگری اهل یک شهر است یا در همان شهر زندگی می‌کند.",faSynonyms:["هم‌وطنِ شهری","اهل یک شهر"],enMeaning:"A person who comes from or lives in the same city as another person.",enSynonyms:["fellow townsman","fellow city resident","townsperson"],arMeaning:"شخصٌ ينتمي إلى المدينة نفسها أو يسكن فيها مع شخصٍ آخر.",arSynonyms:["من أبناء المدينة نفسها","مواطن من المدينة ذاتها"]},
  "هجری قمری":{faMeaning:"تقویمی که مبنای شمارش سال‌های آن هجرت پیامبر اسلام است و ماه‌هایش بر پایهٔ گردش ماه تعیین می‌شوند.",faSynonyms:["تقویم قمری اسلامی","گاه‌شماری هجری قمری"],enMeaning:"The Islamic lunar calendar, whose year count begins with the Hijra and whose months follow lunar cycles.",enSynonyms:["Hijri calendar","Islamic lunar calendar"],arMeaning:"التقويم القمري الإسلامي الذي يبدأ تأريخه بالهجرة وتُحدّد أشهره بحسب دورة القمر.",arSynonyms:["التقويم الهجري","التقويم القمري الإسلامي"]},
  "منجم":{faMeaning:"کسی که اجرام آسمانی و پدیده‌های آسمان را مطالعه می‌کند؛ در کاربرد تاریخی گاهی به ستاره‌بین یا اخترشمار نیز گفته شده است.",faSynonyms:["اخترشناس (در معنای علمی)","ستاره‌شناس"],enMeaning:"A person who studies celestial objects; historically, the word could also refer to an astrologer.",enSynonyms:["astronomer","stargazer","astrologer (historical/contextual)"],arMeaning:"شخصٌ يدرس الأجرام السماوية؛ وقد استُعمل تاريخياً أيضاً لمن يمارس التنجيم.",arSynonyms:["فلكيّ","عالم فلك","منجّم (للمعنى التنجيمي)"]},
  "پیروزی":{faMeaning:"موفق شدن در رقابت، مبارزه یا تلاش و به دست آوردن نتیجهٔ مطلوب.",faSynonyms:["برد","ظفر","موفقیت (گسترده‌تر)"],enMeaning:"Success in a contest, struggle, or effort; achieving the desired result.",enSynonyms:["victory","triumph","win"],arMeaning:"النجاح في منافسةٍ أو صراعٍ أو سعيٍ وتحقيق النتيجة المطلوبة.",arSynonyms:["نصر","فوز","ظفر"]},
