  "برج":{faMeaning:"ساختمانی بلند و معمولاً چندطبقه؛ همچنین در برخی بافت‌ها به یکی از دوازده بخش منطقه‌البروج گفته می‌شود.",faSynonyms:["ساختمان بلند","برج بلند"],enMeaning:"A tall building or structure; in some contexts, one of the twelve zodiac signs.",enSynonyms:["tower","high-rise","zodiac sign (contextual)"],arMeaning:"بناءٌ مرتفع؛ ويُطلق في بعض السياقات على أحد الأبراج الفلكية الاثني عشر.",arSynonyms:["برج","ناطحة (بحسب النوع)","برج فلكي"]},
  "ستون":{faMeaning:"پایه‌ای عمودی که بخشی از ساختمان را نگه می‌دارد؛ همچنین بخش عمودی جدول یا متن.",faSynonyms:["پایه","تیرک","ستون جدول"],enMeaning:"A vertical support in a building; also a vertical division in a table or text.",enSynonyms:["column","pillar","post"],arMeaning:"دعامة عمودية تحمل جزءاً من البناء؛ ويُطلق أيضاً على القسم العمودي في جدول أو نص.",arSynonyms:["عمود","دعامة","عمود جدول"]},
